# Solidity Interface and Implementation Example

Here's a complete example showing an interface and a contract that implements it.

## Interface

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/// @title IToken - A simple token interface
interface IToken {
    // Events
    event Transfer(address indexed from, address indexed to, uint256 amount);
    event Approval(address indexed owner, address indexed spender, uint256 amount);

    // View functions
    function name() external view returns (string memory);
    function symbol() external view returns (string memory);
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);

    // State-changing functions
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}
```

## Implementation

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "./IToken.sol";

/// @title SimpleToken - A basic implementation of IToken
contract SimpleToken is IToken {
    // State variables
    string private _name;
    string private _symbol;
    uint256 private _totalSupply;

    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;

    // Constructor
    constructor(string memory tokenName, string memory tokenSymbol, uint256 initialSupply) {
        _name = tokenName;
        _symbol = tokenSymbol;
        _totalSupply = initialSupply;
        _balances[msg.sender] = initialSupply;

        emit Transfer(address(0), msg.sender, initialSupply);
    }

    // View functions (override interface)
    function name() external view override returns (string memory) {
        return _name;
    }

    function symbol() external view override returns (string memory) {
        return _symbol;
    }

    function totalSupply() external view override returns (uint256) {
        return _totalSupply;
    }

    function balanceOf(address account) external view override returns (uint256) {
        return _balances[account];
    }

    // Transfer tokens to another address
    function transfer(address to, uint256 amount) external override returns (bool) {
        require(to != address(0), "Transfer to zero address");
        require(_balances[msg.sender] >= amount, "Insufficient balance");

        _balances[msg.sender] -= amount;
        _balances[to] += amount;

        emit Transfer(msg.sender, to, amount);
        return true;
    }

    // Approve a spender to spend tokens on your behalf
    function approve(address spender, uint256 amount) external override returns (bool) {
        require(spender != address(0), "Approve to zero address");

        _allowances[msg.sender][spender] = amount;

        emit Approval(msg.sender, spender, amount);
        return true;
    }

    // Transfer tokens on behalf of another address (requires approval)
    function transferFrom(address from, address to, uint256 amount) external override returns (bool) {
        require(from != address(0), "Transfer from zero address");
        require(to != address(0), "Transfer to zero address");
        require(_balances[from] >= amount, "Insufficient balance");
        require(_allowances[from][msg.sender] >= amount, "Insufficient allowance");

        _balances[from] -= amount;
        _balances[to] += amount;
        _allowances[from][msg.sender] -= amount;

        emit Transfer(from, to, amount);
        return true;
    }
}
```

## Key Concepts

| Concept | Description |
|---------|-------------|
| `interface` | Defines a contract's external API without implementation. All functions are implicitly `external` and cannot have a body. |
| `override` | Required keyword when implementing functions declared in an interface. |
| `is IToken` | Indicates the contract inherits from / implements the interface. |
| `event` | Declared in the interface; must be emitted in the implementation. |

## Notes

- **No constructors or state variables** are allowed in interfaces.
- **All interface functions** must be `external` and marked `override` in the implementing contract.
- If you don't implement **all** interface functions, the contract must be declared `abstract`.
- This is a simplified ERC-20-style token — for production use, consider [OpenZeppelin's audited contracts](https://github.com/OpenZeppelin/openzeppelin-contracts).

